import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    p = [0] * (n + 2)
    p[0] = n + 1
    for k in range(n):
        x, y = data[2*k+1:2*k+3]
        p[x] = y
    dp = [0] * (n + 2)
    dp[0] = 1
    for j in range(1, n + 2):
        low = p[j]
        total = 0
        for i in range(j):
            high = p[i]
            if high <= low or not dp[i]:
                continue
            a = [p[k] for k in range(i+1, j) if low < p[k] < high]
            m = len(a)
            if m:
                suffix = [0] * (m + 1)
                for k in range(m-1, -1, -1):
                    suffix[k] = max(suffix[k+1], a[k])
                minimum = n + 1
                valid = True
                for k, v in enumerate(a):
                    if v < minimum and v > suffix[k+1]:
                        valid = False
                        break
                    if v < minimum:
                        minimum = v
                if not valid:
                    continue
            total += dp[i]
        dp[j] = total % MOD
    print(dp[n+1])

if __name__ == '__main__':
    solve()

