import sys

MOD = 998244353


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)

    bounds = [[n + 1] * n for _ in range(n)]
    for _ in range(m):
        l = next(it) - 1
        r = next(it)
        x = next(it) - 1
        if r < bounds[l][x]:
            bounds[l][x] = r

    for l in range(n - 2, -1, -1):
        a = bounds[l]
        b = bounds[l + 1]
        for x in range(l, n):
            if b[x] < a[x]:
                a[x] = b[x]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid count on [l,r), divided by (r-l)!.
    # end is its transpose, for fast access in the inner loop.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    end = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = end[i][i] = 1

    for l in range(n - 1, -1, -1):
        row = dp[l]
        bound = bounds[l]
        for r in range(l + 1, n + 1):
            col = end[r]
            total = 0
            for k in range(l, r):
                if r < bound[k]:
                    total += row[k] * col[k + 1]
            row[r] = col[l] = total * inv[r - l] % MOD

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)


if __name__ == '__main__':
    solve()

