import sys
from collections import deque
from array import array

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n

    # Remove trees from their leaves towards their cycle.
    # dp[v][j] counts assignments below v with v assigned j+1.
    # None represents the all-ones vector.
    while q:
        v = q.popleft()
        p = a[v]
        child = dp[v]
        parent = dp[p]
        if child is None:
            if parent is None:
                dp[p] = array('I', range(1, m + 1))
            else:
                for j in range(m):
                    parent[j] = parent[j] * (j + 1) % MOD
        else:
            s = 0
            if parent is None:
                for j in range(m):
                    s = (s + child[j]) % MOD
                    child[j] = s
                dp[p] = child
            else:
                for j in range(m):
                    s = (s + child[j]) % MOD
                    parent[j] = parent[j] * s % MOD
        dp[v] = None
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    ans = 1
    for start in range(n):
        if deg[start] == 0:
            continue
        # All vertices on this cycle must have the same value.
        product = None
        v = start
        while deg[v]:
            deg[v] = 0
            cur = dp[v]
            if cur is not None:
                if product is None:
                    product = cur
                else:
                    for j in range(m):
                        product[j] = product[j] * cur[j] % MOD
            v = a[v]
        total = m if product is None else sum(product) % MOD
        ans = ans * total % MOD
    print(ans)


if __name__ == '__main__':
    solve()

