import sys
from math import gcd

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                k = 0
                while x % p == 0:
                    x //= p
                    k += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = k
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    ans = 1
    for p, ks in factors.items():
        g = 0
        for k in ks:
            g = gcd(g, k)
        ks = [k // g for k in ks]
        base = pow(p, g, MOD)
        powers = [1] * (sum(ks) + 1)
        for j in range(1, len(powers)):
            powers[j] = powers[j - 1] * base % MOD

        # Heights are normalized so that the smallest height so far is zero.
        dp = [1]
        for i, k in enumerate(ks, 1):
            length = len(dp)
            if k == 0:
                for h in range(length):
                    dp[h] = dp[h] * powers[h] % MOD
                continue

            nd = [0] * (length + k)
            for h in range(length + k):
                value = dp[h - k] if h >= k else 0
                if h + k < length:
                    value += dp[h + k]
                nd[h] = value * powers[h] % MOD

            # A new minimum raises all i previous heights by k-h.
            for h in range(min(k, length)):
                nd[0] = (nd[0] + dp[h] * pow(base, (k - h) * i, MOD)) % MOD
            dp = nd

        ans = ans * sum(dp) % MOD
    print(ans)


if __name__ == '__main__':
    solve()

