import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    a = data[1:]
    m = max(a)
    values = list(set(a))
    ids = [-1] * (m + 1)
    for i, x in enumerate(values):
        ids[x] = i
    phi = list(range(m + 1))
    for p in range(2, m + 1):
        if phi[p] == p:
            for x in range(p, m + 1, p):
                phi[x] -= phi[x] // p
    groups = {}
    for d in range(1, m + 1):
        members = tuple(ids[x] for x in range(d, m + 1, d) if ids[x] >= 0)
        if members:
            groups[members] = groups.get(members, 0) + phi[d]
    edges = [[] for _ in values]
    weights = []
    for members, w in groups.items():
        j = len(weights)
        weights.append(w)
        for i in members:
            edges[i].append(j)
    del groups
    counts = [0] * len(weights)
    mod = 998244353
    power = 1
    ans = 0
    out = []
    for x in a:
        q = 0
        for d in edges[ids[x]]:
            q += weights[d] * counts[d]
            counts[d] += power
        ans = (2 * ans + q) % mod
        power = power * 2 % mod
        out.append(str(ans))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

