from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        gains = [0] * len(conflictingPairs)
        first = second = 0
        owner = 0
        total = 0

        for right in range(1, n + 1):
            # Keep the two largest active lower endpoints, including ties.
            for a, i in buckets[right]:
                if a > first:
                    second = first
                    first = a
                    owner = i
                elif a > second:
                    second = a

            total += right - first
            # Only removing the strongest constraint can help this endpoint.
            gains[owner] += first - second

        return total + max(gains)

