import sys


def solve(A, B, mod):
    # Complementing a permutation exchanges A and B.
    if A > B:
        A, B = B, A

    bits = B.bit_length()
    mask = (1 << bits) - 1
    steps = [1 << (bits * i) for i in range(A)]

    # Count insertion tableaux whose last-column bumping path is possible.
    dp = {0: 1}
    for _ in range(A * B - 1):
        nxt = {}
        for state, ways in dp.items():
            remaining = state
            previous = B
            for col in range(A):
                height = remaining & mask
                remaining >>= bits
                if height < previous and (col != A - 1 or height + 1 < previous):
                    new_state = state + steps[col]
                    nxt[new_state] = (nxt.get(new_state, 0) + ways) % mod
                previous = height
        dp = nxt
    insertion_count = next(iter(dp.values()))

    # Hook-length formula for the recording tableaux of shape
    # (A, A, ..., A, A-1).
    factorial = 1
    for value in range(1, A * B):
        factorial = factorial * value % mod

    hook_product = 1
    for row in range(B):
        length = A - (row == B - 1)
        for col in range(length):
            below = B - 1 - row - (col == A - 1)
            hook_product = hook_product * (length - col + below) % mod

