import sys
from math import gcd


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    rows = []
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # The first machine has at least as good a capacity/cost ratio.
        if a * q < b * p:
            a, p, b, q = b, q, a, p
        # a/g units of the second machine can be replaced by b/g
        # units of the first, preserving capacity without increasing cost.
        options = [(b * y, q * y) for y in range(a // gcd(a, b))]
        rows.append((a, p, options))

    lo, hi = 0, budget * 100 + 1
    while hi - lo > 1:
        w = (lo + hi) // 2
        total = 0
        for a, p, options in rows:
            best = ((w + a - 1) // a) * p
            for capacity, cost in options:
                if capacity >= w:
                    if cost < best:
                        best = cost
                    break
                candidate = ((w - capacity + a - 1) // a) * p + cost
                if candidate < best:
                    best = candidate
            total += best
            if total > budget:
                break
        if total <= budget:
            lo = w
        else:
            hi = w
    print(lo)


if __name__ == '__main__':
    solve()

