import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for i in range(m):
        u, v = data[2 + 2 * i] - 1, data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row-echelon form over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        p = next((i for i in range(rank, n) if rows[i] >> col & 1), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and rows[i] >> col & 1:
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [i for i in range(n) if i not in pivot_set]
    ans = [0] * n
    # Each output bit is one nullspace basis vector.
    for k, col in enumerate(free):
        ans[col] = 1 << k
        for i, pivot in enumerate(pivots):
            if rows[i] >> col & 1:
                ans[pivot] |= 1 << k

    # A zero coordinate here is zero in every nullspace vector.
    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)


