import sys
from math import isqrt


def solve(n):
    # Set d = x - y. Then n/d = 3*y*y + 3*d*y + d*d.
    for d in range(1, 1000001):
        d2 = d * d
        if d2 * d >= n:
            break
        if n % d:
            continue

        q = n // d
        discriminant = 12 * q - 3 * d2
        s = isqrt(discriminant)
        if s * s == discriminant and s > 3 * d and (s - 3 * d) % 6 == 0:
            y = (s - 3 * d) // 6
            return f'{y + d} {y}'
    return '-1'


