class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        groups = deque()
        right = len(nums) - 1
        cost = answer = 0
        for left in range(len(nums) - 1, -1, -1):
            value = nums[left]
            count = 1
            while groups and groups[-1][0] < value:
                old, size = groups.pop()
                cost += (value - old) * size
                count += size
            groups.append((value, count))
            while cost > k:
                level, size = groups.popleft()
                cost -= level - nums[right]
                right -= 1
                if size > 1:
                    groups.appendleft((level, size - 1))
            answer += right - left + 1
