class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        answer = len(s)
        for target in range(1, max(counts) + 1):
            dp0 = counts[0]
            dp1 = abs(counts[0] - target)
            previous = counts[0]
            for current in counts[1:]:
                best = min(dp0, dp1)
                new0 = best + current
                if current >= target:
                    new1 = best + current - target
                else:
                    deficit = target - current
                    new1 = min(dp0 + max(0, deficit - previous),
                               dp1 + max(0, deficit - max(0, previous - target)))
                dp0, dp1 = new0, new1
                previous = current
            answer = min(answer, dp0, dp1)
        return answer

