import sys

MOD = 998244353


def solve(h, w, grid):
    if any(row.count(b'A') & 1 for row in grid):
        return 0

    n = h + w
    parent = list(range(n))
    size = [1] * n
    parity = bytearray(n)
    cols = bytearray(w)
    components = n

    def find(x):
        value = 0
        while parent[x] != x:
            p = parent[x]
            parity[x] ^= parity[p]
            parent[x] = parent[p]
            value ^= parity[x]
            x = parent[x]
        return x, value

    for i, row in enumerate(grid):
        r = 0
        for j, ch in enumerate(row):
            if ch == 65:
                r ^= 1
                cols[j] ^= 1
            else:
                a, pa = find(i)
                b, pb = find(h + j)
                v = 1 ^ r ^ cols[j] ^ pa ^ pb
                if a == b:
                    if v:
                        return 0
                else:
                    if size[a] < size[b]:
                        a, b = b, a
                    parent[b] = a
                    parity[b] = v
                    size[a] += size[b]
                    components -= 1

    if any(cols):
        return 0
    return pow(2, components, MOD)


def main():
    data = sys.stdin.buffer
    t = int(data.readline())
    answers = []
    for _ in range(t):
        h, w = map(int, data.readline().split())
        grid = [data.readline().strip() for _ in range(h)]
        answers.append(str(solve(h, w, grid)))
    sys.stdout.write('\n'.join(answers))


if __name__ == '__main__':
    main()

