import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    h, w = data[0], data[1]
    n = h * w
    heights = data[2:2 + n]
    order = sorted(range(n), key=heights.__getitem__, reverse=True)

    # Each newly activated vertex joins the roots of adjacent components.
    uf = list(range(n))
    parent = list(range(n))
    active = bytearray(n)
    for v in order:
        active[v] = 1
        col = v % w
        neighbors = []
        if v >= w:
            neighbors.append(v - w)
        if v + w < n:
            neighbors.append(v + w)
        if col:
            neighbors.append(v - 1)
        if col + 1 < w:
            neighbors.append(v + 1)
        for u in neighbors:
            if active[u]:
                while uf[u] != u:
                    uf[u] = uf[uf[u]]
                    u = uf[u]
                if u != v:
                    parent[u] = v
                    uf[u] = v

    # Heavy-light decomposition of the component merge tree.
    size = [1] * n
    heavy = [-1] * n
    for v in order:
        p = parent[v]
        if p != v:
            size[p] += size[v]
            if heavy[p] == -1 or size[v] > size[heavy[p]]:
                heavy[p] = v

    depth = [0] * n
    head = list(range(n))
    for v in reversed(order):
        p = parent[v]
        if p != v:
            depth[v] = depth[p] + 1
            if heavy[p] == v:
                head[v] = head[p]

    pos = 2 + n
    q = data[pos]
    pos += 1
    out = []
    for _ in range(q):
        a, b, y, c, d, z = data[pos:pos + 6]
        pos += 6
        u = (a - 1) * w + b - 1
        v = (c - 1) * w + d - 1
        while head[u] != head[v]:
            if depth[head[u]] > depth[head[v]]:
                u = parent[head[u]]
            else:
                v = parent[head[v]]
        lca = u if depth[u] < depth[v] else v
        level = min(y, z, heights[lca])
        out.append(str(y + z - 2 * level))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    solve()

