import sys


def solve(n, a, b):
    if a == b:
        return 0
    aa = [i for i, c in enumerate(a) if c == 49]
    bb = [i for i, c in enumerate(b) if c == 49]
    m = len(bb)
    if m > len(aa):
        return -1
    if m == 1:
        return max(abs(aa[0] - bb[0]), abs(aa[-1] - bb[0]))

    def ok(t):
        prev = bb[0] - aa[0]
        if not -t <= prev <= t:
            return False
        j = 0
        it = iter(aa)
        next(it)
        for x in it:
            k = j + 1
            if k < m:
                d = bb[k] - x
                if d <= t and (d < prev or d == prev and not ((d ^ t) & 1)):
                    if d < -t:
                        return False
                    j = k
                    prev = d
                    continue
            prev = bb[j] - x
            if prev < -t:
                return False
        return j == m - 1

    lower = max(abs(aa[0] - bb[0]), abs(aa[-1] - bb[-1]))
    ans = n + 1
    for p in range(2):
        lo = (lower - p + 1) // 2
        if ok(2 * lo + p):
            ans = min(ans, 2 * lo + p)
            continue
        hi = (min(n, ans - 1) - p) // 2
        if hi <= lo or not ok(2 * hi + p):
            continue
        while hi - lo > 1:
            mid = (hi + lo) // 2
            if ok(2 * mid + p):
                hi = mid
            else:
                lo = mid
        ans = min(ans, 2 * hi + p)
    return ans if ans <= n else -1


