import sys
import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[:2]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, 2 * n + 2, 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        old = dp
        dp = old.copy()
        gain = 0
        for k in range(1, W // w + 1):
            marginal = -heap[0]
            if marginal <= 0:
                break
            gain += marginal
            heapq.heapreplace(heap, 2 - marginal)
            weight = k * w
            for capacity, base in enumerate(old[:W - weight + 1], weight):
                val = base + gain
                if val > dp[capacity]:
                    dp[capacity] = val

    print(dp[W])


