import sys


def possible(s, t, k):
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False

    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    if i == n and i == m:
        return True

    # For each diagonal d = i - j, keep the furthest reachable i.
    prev = {0: i}
    for e in range(1, k + 1):
        curr = {}
        for d in range(max(-e, -m), min(e, n) + 1):
            best = -1

            # Replace a character.
            p = prev.get(d, -1)
            if p >= 0 and p < n and p - d < m:
                best = p + 1

            # Delete a character from s.
            p = prev.get(d - 1, -1)
            if p >= 0 and p < n:
                best = max(best, p + 1)

            # Insert a character into s.
            p = prev.get(d + 1, -1)
            if p >= 0 and p - d - 1 < m:
                best = max(best, p)

            if best < 0:
                continue
            i = best
            j = i - d
            while i < n and j < m and s[i] == t[j]:
                i += 1
                j += 1
            if i == n and j == m:
                return True
            curr[d] = i
        prev = curr
    return False


def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    print('Yes' if possible(data[1], data[2], k) else 'No')


if __name__ == '__main__':
    main()

