class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        a = b = prev_a = prev_b = 0
        for x, y in zip(energyDrinkA, energyDrinkB):
            # Continue the same drink, or switch after one idle hour.
            a, b, prev_a, prev_b = (
                max(a, prev_b) + x,
                max(b, prev_a) + y,
                a,
                b,
            )
        return max(a, b)

