from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        minima = [float('inf')] * k
        minima[0] = 0
        prefix = 0
        answer = -float('inf')
        for i, value in enumerate(nums, 1):
            prefix += value
            r = i % k
            candidate = prefix - minima[r]
            if candidate > answer:
                answer = candidate
            if prefix < minima[r]:
                minima[r] = prefix
        return answer

