from itertools import permutations


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    g = [[0] * n for _ in range(n)]
    h = [[0] * n for _ in range(n)]

    for _ in range(next(it)):
        u, v = next(it) - 1, next(it) - 1
        g[u][v] = g[v][u] = 1
    for _ in range(next(it)):
        u, v = next(it) - 1, next(it) - 1
        h[u][v] = h[v][u] = 1

    pairs = [(i, j, next(it)) for i in range(n) for j in range(i + 1, n)]
    best = sum(w for i, j, w in pairs) + 1

    # p maps each vertex of H to its corresponding vertex of G.
    for p in permutations(range(n)):
        cost = 0
        for i, j, w in pairs:
            if g[p[i]][p[j]] != h[i][j]:
                cost += w
        if cost < best:
            best = cost
            if best == 0:
                break

    print(best)


