from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        ans = 0
        lcp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            prefix = z[i] >= i
            if prefix:
                ans += n - 2 * i
            cutoff = 2 * i if prefix else n
            value = nums[i]
            # Ascending j preserves the previous row's lcp[j + 1].
            for j in range(i + 1, n):
                if nums[j] == value:
                    length = lcp[j + 1] + 1
                    lcp[j] = length
                    if length >= j - i and j < cutoff:
                        ans += 1
                else:
                    lcp[j] = 0
        return ans

