import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # A reverse spanning tree gives each non-root node one outgoing edge
        # in the original graph, satisfying every allowed threshold.
        reverse = [[] for _ in range(n)]
        for u, v, w in edges:
            reverse[v].append((u, w))

        dist = [1000001] * n
        dist[0] = 0
        heap = [(0, 0)]
        count = 0

        while heap:
            cost, u = heapq.heappop(heap)
            if cost != dist[u]:
                continue
            count += 1
            if count == n:
                return cost
            for v, w in reverse[u]:
                candidate = max(cost, w)
                if candidate < dist[v]:
                    dist[v] = candidate
                    heapq.heappush(heap, (candidate, v))

        return -1

