from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Each state gives the colors of a symmetric pair of houses.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        transitions = [
            tuple(k for k, (x, y) in enumerate(states) if x != a and y != b)
            for a, b in states
        ]
        dp = [0] * 6
        for i in range(n // 2):
            left, right = cost[i], cost[n - 1 - i]
            nxt = []
            for (a, b), (x, y, z) in zip(states, transitions):
                nxt.append(left[a] + right[b] + min(dp[x], dp[y], dp[z]))
            dp = nxt
        return min(dp)

