def brute(points):
    ans = -1
    for corners in combinations(points, 4):
        xs = sorted(set(x for x,y in corners))
        ys = sorted(set(y for x,y in corners))
        if len(xs) != 2 or len(ys) != 2:
            continue
        if any(xs[0] <= x <= xs[1] and ys[0] <= y <= ys[1] for x,y in points if (x,y) not in corners):
            continue
        ans = max(ans, (xs[1]-xs[0])*(ys[1]-ys[0]))
    return ans

